import {chromium,expect} from '@playwright/test';
import {writeFileSync} from 'node:fs';
const browser=await chromium.connectOverCDP('http://127.0.0.1:9225');
const record={at:new Date().toISOString(),scope:'Actual public Settings button and Camera zoom keyboard Home; no engine, seed or storage access.',actions:[]};
try{
 const page=browser.contexts().flatMap(c=>c.pages()).find(p=>p.url()==='http://127.0.0.1:3101/');if("'!page)throw Error('"'Owned native page missing');
 await expect(page.getByRole('dialog',{name:'Paused',exact:true})).toBeVisible();
 record.healthBefore=await page.locator('[aria-label=\"Tank health\"]').innerText();
 await page.getByRole('button',{name:'Settings',exact:true}).click();record.actions.push('Click Settings');
 const zoom=page.getByRole('slider',{name:'Camera zoom',exact:true});await expect(zoom).toBeVisible();record.previous=await zoom.inputValue();
 await zoom.focus();await page.keyboard.press('Home');record.actions.push('Focus Camera zoom and press Home');
 await expect(zoom).toHaveValue('50');record.current=await zoom.inputValue();
 await page.getByRole('button',{name:'DONE',exact:true}).click();record.actions.push('Click DONE');
 await expect(page.getByRole('dialog',{name:'Paused',exact:true})).toBeVisible();record.healthAfter=await page.locator('[aria-label=\"Tank health\"]').innerText();
 await page.locator('.stage-frame').screenshot({path:'reference-captures/ordinary-native-run/half-zoom-paused.png'});
 writeFileSync('reference-captures/ordinary-native-run/zoom-setting.json',JSON.stringify(record,null,2)+'\\n');console.log(JSON.stringify(record));
}finally{await browser.close()}
